// Who you cook with, filled in when the template is added.
const WHO = {{who}};
const INK = '#121a2e';
const MINT = { light: '#a9e9cd', dark: '#183b34' };
const WORDS = { light: INK, dark: '#d6f7ea' };
const FACE = { light: '#FFFFFF', dark: '#24544a' };
const FACE_WORDS = { light: INK, dark: '#FFFFFF' };
const RIM = { light: '#121a2e52', dark: '#d6f7ea80' };
const RIM_OUT = { light: '#121a2e52', dark: '#d6f7ea59' };
const KEY = { light: INK, dark: '#8ee4c0' };
const KEY_WORDS = { light: '#a9e9cd', dark: '#102923' };
const PLATE = 'M3 11h18a9 9 0 0 1-18 0z M9 7.5c0-1.5 1-1.5 1-3.5M14 7.5c0-1.5 1-1.5 1-3.5';

// The faces and the key sit twice: solid in the backdrop, which tinted and clear mode remove, and faint in the
// tree with their words. So in full color they read as solid, and in tinted mode the words still show.
function scene(u, ghost, cook, key) {
  const face = (label, on) => ({ type: 'zstack', frame: { width: 34 * u, height: 34 * u },
    opacity: on ? 1 : 0.55, children: [
      on && { type: 'circle', fill: ghost ? FACE : { light: '#FFFFFF40', dark: '#24544a40' } },
      !ghost && { type: 'circle', stroke: on ? { color: RIM, width: 1.5 * u }
        : { color: RIM_OUT, width: 1.5 * u, dash: [3 * u, 2.4 * u] } },
      !ghost && { type: 'text', value: label, size: 13 * u, weight: 'heavy', color: FACE_WORDS, lineLimit: 1,
        minScale: 0.6 },
    ] });
  return [
    { type: 'hstack', spacing: 6 * u, padding: { top: 43.5 * u, leading: 16 * u },
      frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
      children: [face(initial(WHO), cook === 'them'), face('Me', cook === 'me')] },
    { type: 'zstack', padding: { leading: 15 * u, bottom: 15 * u },
      frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
      children: [
        { type: ghost ? 'zstack' : 'button', action: ghost ? null : key.action, rowId: ghost ? null : key.rowId,
          children: [
            { type: 'zstack', padding: { vertical: 7 * u, horizontal: 11 * u },
              background: { type: 'rect', cornerRadius: 10 * u,
                fill: ghost ? KEY : { light: '#121a2e40', dark: '#8ee4c040' } },
              children: [
                { type: 'text', value: key.label, size: 12.5 * u, weight: 'bold', color: KEY_WORDS,
                  opacity: ghost ? 0 : 1 },
              ] } ] },
      ] },
  ];
}

function initial(name) {
  const first = Array.from(name.trim())[0] || '?';
  return first.toUpperCase();
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall.
  const u = ctx.height / 170;
  const d = ctx.data;
  const cook = !d.cook ? null : d.cook.by.me ? 'me' : 'them';
  const line = cook === 'me' ? "You're cooking, " + WHO + "'s on dishes"
    : cook === 'them' ? WHO + "'s cooking, you're on dishes" : "Who's cooking tonight?";
  const key = cook === 'me' && d.mine ? { action: 'unsay', rowId: d.mine.id, label: 'Swap back' }
    : { action: 'cook', label: "I'll cook" };

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: MINT,
      children: scene(u, true, cook, key) },
    children: [
      { type: 'vstack', padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' }, children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: PLATE, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
              stroke: { color: WORDS, width: 2.4 * 15 * u / 24, cap: 'round' } },
            { type: 'text', value: 'Dinner tonight', size: 13 * u, weight: 'bold', color: WORDS, lineLimit: 1,
              minScale: 0.8 } ] } ] },
      scene(u, false, cook, key),
      { type: 'text', value: line, size: 12.5 * u, weight: 'semibold', color: WORDS, opacity: 0.8, lineLimit: 2,
        minScale: 0.5, padding: { top: 82.5 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' } },
    ],
  };
}
